import React, { useState } from 'react';
import Animation from './components/Animation';
import Controls from './components/Controls';

const App: React.FC = () => {
    const [outer, setOuter] = useState(false);
    const [onlySuggestions, setOnlySuggestions] = useState(false);
    const [success, setSuccess] = useState(false);
    const [warning, setWarning] = useState(false);

    return (
        <div>
            <h1>Rive Animation</h1>
            <Animation 
                outer={outer} 
                onlySuggestions={onlySuggestions} 
                success={success} 
                warning={warning} 
            />
            <Controls 
                outer={outer} setOuter={setOuter} 
                onlySuggestions={onlySuggestions} setOnlySuggestions={setOnlySuggestions} 
                success={success} setSuccess={setSuccess} 
                warning={warning} setWarning={setWarning} 
            />
        </div>
    );
};

export default App;
